// Prepare GraphQL query to fetch full issue details
const issueId = $input.first().json.data.id;
const teamId = $input.first().json.data.teamId;

const query = `query($issueId: String!) {
  issue(id: $issueId) {
    id
    identifier
    title
    description
    priority
    url
    estimate
    labels { nodes { name } }
    assignee { name email }
    team { name id }
    parent { title identifier description }
    children { nodes { identifier title description state { name } priority } }
    comments(first: 50) { nodes { body user { name } createdAt } }
    relations { nodes { type relatedIssue { title identifier description } } }
  }
}`;

return [{
  json: {
    query,
    variables: { issueId },
    _teamId: teamId
  }
}];

const issue = $input.first().json.data.issue;

// --- Build Context ---
let context = `## Task Information\n`;
context += `- **Identifier:** ${issue.identifier}\n`;
context += `- **Title:** ${issue.title}\n`;
context += `- **Priority:** ${['None','Urgent','High','Medium','Low'][issue.priority] || 'None'}\n`;
context += `- **Labels:** ${issue.labels?.nodes?.map(l => l.name).join(', ') || 'None'}\n`;
context += `- **Assignee:** ${issue.assignee?.name || 'Unassigned'}\n`;

if (issue.parent) {
  context += `- **Epic/Parent:** ${issue.parent.identifier} - ${issue.parent.title}\n`;
  if (issue.parent.description) context += `  - ${issue.parent.description.substring(0, 300)}\n`;
}
if (issue.estimate) context += `- **Estimate:** ${issue.estimate} points\n`;

context += `\n### Original Description\n${issue.description || 'No description provided.'}\n`;

if (issue.children?.nodes?.length > 0) {
  context += `\n### Sub-Tasks (${issue.children.nodes.length})\n`;
  for (const c of issue.children.nodes) {
    context += `- [${c.state?.name === 'Done' ? 'x' : ' '}] **${c.identifier}** (${c.state?.name || '?'}): ${c.title}`;
    if (c.description) context += ` — ${c.description.substring(0, 150)}`;
    context += `\n`;
  }
}

if (issue.comments?.nodes?.length > 0) {
  context += `\n### Team Discussion (${issue.comments.nodes.length} comments)\n`;
  const sorted = [...issue.comments.nodes].sort((a,b) => new Date(a.createdAt) - new Date(b.createdAt));
  for (const c of sorted) {
    const d = new Date(c.createdAt).toISOString().split('T')[0];
    context += `- **@${c.user?.name || '?'}** (${d}): ${c.body?.substring(0, 500) || ''}\n`;
  }
}

if (issue.relations?.nodes?.length > 0) {
  context += `\n### Related Issues\n`;
  for (const r of issue.relations.nodes) {
    const ri = r.relatedIssue;
    context += `- ${r.type}: **${ri.identifier}** — ${ri.title}\n`;
  }
}

// --- System Prompt ---
const systemPrompt = `You are a Senior Product Manager at Çay Hesabım, a digital platform for tea producers (NestJS backend + Vue.js frontend).

Transform the Linear ticket into a comprehensive PRD.

Rules:
1. Include EVERYTHING a developer needs before coding
2. User Stories: "As a [user], I want [action], so that [benefit]"
3. Acceptance Criteria: testable bullet points
4. Think about Edge Cases and error scenarios
5. Separate Backend (NestJS endpoints, DTOs, Services) and Frontend (Vue components, Pinia stores)
6. Include UI/UX notes for designers
7. Write in clear English

Format:
# [Feature Name] — PRD\n\n## 📋 Overview\n[What and why]\n\n## 🎯 Goals & Objectives\n- Goal 1\n\n## 👤 User Stories\n1. **[Title]**\n   - As a [user], I want [action], so that [benefit]\n   - **Acceptance Criteria:**\n     - [ ] Criterion\n\n## 🏗️ Technical Requirements\n### Backend (NestJS)\n- [ ] Endpoints, DTOs, Services, Entity changes\n### Frontend (Vue.js)\n- [ ] Components, Stores, Routes, Composables\n\n## 🎨 UI/UX Notes\n- Design guidelines, responsive, accessibility\n\n## ⚠️ Edge Cases & Error Scenarios\n1. Scenario: Expected behavior\n\n## 📊 Success Metrics\n- KPIs\n\n## 🔗 Dependencies\n- Blockers\n\n## 📝 Out of Scope\n- Not included\n\n---\n*Auto-generated PRD. PM approval required.*`;

return [{
  json: {
    openaiBody: {
      model: 'gpt-4o',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: `Generate a PRD for this Linear ticket:\n\n${context}` }
      ],
      max_tokens: 4096,
      temperature: 0.7
    },
    issueId: issue.id,
    issueIdentifier: issue.identifier,
    issueTitle: issue.title,
    issueUrl: issue.url,
    teamId: issue.team?.id || ''
  }
}];

const response = $input.first().json;
const prdContent = response.choices?.[0]?.message?.content || 'PRD generation failed.';

// Get issue metadata from earlier node
const meta = $node['Build AI Prompt'].json;

// --- Prepare Create Document mutation ---
const createDocBody = {
  query: `mutation($title: String!, $content: String!) {
    documentCreate(input: { title: $title, content: $content }) {
      success
      document { id url slugId }
    }
  }`,
  variables: {
    title: `PRD: ${meta.issueIdentifier} — ${meta.issueTitle}`,
    content: prdContent
  }
};

return [{
  json: {
    createDocBody,
    prdContent,
    issueId: meta.issueId,
    issueIdentifier: meta.issueIdentifier,
    issueTitle: meta.issueTitle,
    issueUrl: meta.issueUrl,
    teamId: meta.teamId
  }
}];

const docResponse = $input.first().json;
const docUrl = docResponse.data?.documentCreate?.document?.url || '';
const docId = docResponse.data?.documentCreate?.document?.id || '';

const meta = $node['Prepare Document Creation'].json;

// --- Attach document to issue ---
const attachBody = {
  query: `mutation($issueId: String!, $url: String!, $title: String!) {
    attachmentCreate(input: { issueId: $issueId, url: $url, title: $title, subtitle: "Auto-generated PRD" }) {
      success
      attachment { id }
    }
  }`,
  variables: {
    issueId: meta.issueId,
    url: docUrl,
    title: `📄 PRD: ${meta.issueTitle}`
  }
};

// --- Lookup PRD Review state ---
const stateQuery = {
  query: `query($teamId: ID!) {
    team(id: $teamId) {
      states { nodes { id name } }
    }
  }`,
  variables: { teamId: meta.teamId }
};

return [{
  json: {
    attachBody,
    stateQuery,
    issueId: meta.issueId,
    issueIdentifier: meta.issueIdentifier,
    issueTitle: meta.issueTitle,
    issueUrl: meta.issueUrl,
    docUrl,
    teamId: meta.teamId
  }
}];

const statesResponse = $input.first().json;
const states = statesResponse.data?.team?.states?.nodes || [];
const prdReviewState = states.find(s => s.name === 'PRD Review');

if (!prdReviewState) {
  throw new Error('Status "PRD Review" not found in Linear. Please create it in Team Settings → Workflow.');
}

const meta = $node['Prepare Attachment & State Lookup'].json;

// --- Update issue status ---
const updateStatusBody = {
  query: `mutation($issueId: String!, $stateId: String!) {
    issueUpdate(id: $issueId, input: { stateId: $stateId }) {
      success
    }
  }`,
  variables: {
    issueId: meta.issueId,
    stateId: prdReviewState.id
  }
};

// --- Add comment ---
const commentBody = {
  query: `mutation($issueId: String!, $body: String!) {
    commentCreate(input: { issueId: $issueId, body: $body }) {
      success
    }
  }`,
  variables: {
    issueId: meta.issueId,
    body: `## 🤖 AI PRD Generated\n\nA comprehensive PRD has been automatically generated for this issue.\n\n📄 **[View PRD Document](${meta.docUrl})**\n\n### Next Steps:\n1. Review the PRD for accuracy and completeness\n2. If approved → move this issue to **Todo**\n3. If changes needed → move back to **Backlog** and add revision comments\n\n---\n*Generated by AI PRD Workflow on ${new Date().toISOString().split('T')[0]}*`
  }
};

return [{
  json: {
    updateStatusBody,
    commentBody
  }
}];
